      (function(){ var b=document.getElementById('enable-demo-btn'); if(!b) return; b.addEventListener('click', function(){ try { var url=new URL(window.location.href); url.searchParams.set('demo','true'); window.location.href=url.toString(); } catch(e) { window.location.search='?demo=true'; } }); })();
      </script>
        <!------------- DEMO: PREVIEW PANEL (?DEMO=TRUE) ------------->
    </body>

</html>